 plan=read(old/'installed-review.plan.json');parts=Path(plan['packed_parts_manifest']);shutil.copy2(parts,d/'parts-manifest.json');plan['packed_parts_manifest']=str(d/'parts-manifest.json');plan['packed_parts_manifest_sha256']=sha(d/'parts-manifest.json');write(d/'entry.plan.json',plan)
